package com.ruchronos.manager;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class AuthAndDeviceIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;
 String login()throws Exception{return mapper.readTree(mvc.perform(post("/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin\",\"password\":\"admin\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get("accessToken").asText();}
 @Test void mockLoginAndMeWork()throws Exception{mvc.perform(get("/me").header("Authorization","Bearer "+login())).andExpect(status().isOk()).andExpect(jsonPath("$.username").value("admin")).andExpect(jsonPath("$.roles[0]").value("admin"));}
 @Test void devicesCrud()throws Exception{String h="Bearer "+login();String body=mvc.perform(post("/me/devices").header("Authorization",h).contentType(MediaType.APPLICATION_JSON).content("{\"provider\":\"fcm\",\"pushToken\":\"test-token\",\"platform\":\"android\",\"deviceName\":\"Pixel test\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();String id=mapper.readTree(body).get("id").asText();mvc.perform(get("/me/devices").header("Authorization",h)).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(id));mvc.perform(delete("/me/devices/"+id).header("Authorization",h)).andExpect(status().isNoContent());mvc.perform(get("/me/devices").header("Authorization",h)).andExpect(status().isOk()).andExpect(jsonPath("$",org.hamcrest.Matchers.hasSize(0)));}
 @Test void errorsUseProblemJson()throws Exception{mvc.perform(get("/me")).andExpect(status().isUnauthorized()).andExpect(content().contentTypeCompatibleWith("application/problem+json")).andExpect(jsonPath("$.code").value("UNAUTHORIZED"));}
}
